ceiling = 100000000;
const endpointBits = P.map((_, i) =>
  G.filter(([u]) => u === i).reduce((bits, [, , bit]) => bits | bit, 0n)
);
const directions = [[0n,1n],[1n,17n],[1n,0n],[1n,4n],[2n,5n],[1n,9n],[3n,17n],[1n,1n],[19n,28n],[1n,30n],[3n,77n],[3n,40n],[3n,1n],[3n,38n],[3n,53n],[2n,73n],[1n,11n]];
const groups = directions.map(([T,U]) => P
  .flatMap(([t,b,d], id) => {
    if (id === 24 || T*b !== U*t) return [];
    const r = T ? t/T : b/U;
    if (r <= 0n || t !== r*T || b !== r*U || d < 0n) throw Error("invalid ordinate");
    // e=x+17y+275z, f=-y-18z, c=z.
    return [{id, r, d, threshold: [-T*d*r, (U-17n*T)*d*r, -d*d+(18n*U-275n*T)*d*r, r*r]}];
  })
  .sort((a,b) => sg(a.d*b.r-b.d*a.r))
);
if (P[24].join() !== "0,0,1" || new Set(groups.flat().map(x => x.id)).size !== 50) throw Error("endpoint coverage");
if (groups.some(g => g.some((x, i) => i && x.d*g[i-1].r <= g[i-1].d*x.r))) throw Error("duplicate ordinate");
if(groups[0].map(x=>x.id).join()!=="18,2,0,36") throw Error("unexpected infinity pencil");
const interceptRows = directions.map(([T,U]) => [T*T,T*U,U*U]);
const circuits = directions.map((_,k) => {
  const tests = [];
  for (let i=0;i<k;i++) for (let j=i+1;j<k;j++) for (let h=j+1;h<k;h++) {
    const indices = [i,j,h,k];
    const weights = indices.map((_, a) => {
      const [x,y,z] = indices.filter((_,b) => a!==b).map(o => interceptRows[o]);
      return (a%2 ? -1n : 1n) * dot(x, cross(y,z));
    });
    if (weights.some(w => !w) || [0,1,2].some(
      a => indices.reduce((s,o,j) => s+weights[j]*interceptRows[o][a],0n)
    )) throw Error("invalid intercept circuit");
    tests.push({indices,weights});
  }
  return tests;
});


const wall=[1n,0n,0n];
function difference(a,b) {
  return norm(a.slice(0,3).map((x,i)=>x*b[3]-b[i]*a[3]));
}

// All real monic quadratics on n sorted ordinates have exactly
// these words, including every one- and two-zero possibility.
function variablePatterns(group) {
  const n=group.length;
  const words=[];
  function emit(left,right,zeros) {
    const signs=group.map((_,i)=>zeros.includes(i)?0:i>=left&&i<=right?-1:1);
    let p=0n,n=0n;
    const lower=[],upper=[],cuts=[];
    const start=group[zeros[0]]?.threshold;
    if(start) {
      lower.push(start);upper.push(start);
      for(const i of zeros.slice(1)) {
        const row=difference(group[i].threshold,start);
        cuts.push({row,strict:false},{row:scale(row,-1n),strict:false});
      }
    }
    for(const [i,x] of group.entries()) {
      if(signs[i]>0) {
        p|=endpointBits[x.id];
        if(start) cuts.push({row:difference(start,x.threshold),strict:true});
        else lower.push(x.threshold);
      } else if(signs[i]<0) {
        n|=endpointBits[x.id];
        if(start) cuts.push({row:difference(x.threshold,start),strict:true});
        else upper.push(x.threshold);
      }
    }
    if(!start) for(const u of upper) for(const l of lower) {
      cuts.push({row:difference(u,l),strict:true});
    }
    words.push({p,n,lower,upper,cuts,zero:zeros.length>0});
  }
  emit(1,0,[]);
  for(let left=0;left<n;left++) for(let right=left;right<n;right++) emit(left,right,[]);
  for(let i=0;i<n;i++) {
    emit(1,0,[i]);
    for(let j=0;j<i;j++) emit(j,i-1,[i]);
    for(let j=i+1;j<n;j++) emit(i+1,j,[i]);
    for(let j=i+1;j<n;j++) emit(i+1,j-1,[i,j]);
  }
  if(words.length!==1+2*n*n||new Set(words.map(x=>x.p+","+x.n)).size!==words.length) throw Error("ternary word census");
  return words;
}

function fixedPatterns(members,k) {
  const words=[];
  function emit(j,z) {
    const positiveFrom=j+z;
    let p=0n,n=0n;
    for(let i=0;i<j;i++) n|=endpointBits[members[i].id];
    for(let i=positiveFrom;i<members.length;i++) p|=endpointBits[members[i].id];
    const anchor=z ? members[j].threshold : null;
    const lower=anchor??members[positiveFrom]?.threshold;
    const upper=anchor??members[j-1]?.threshold;
    const sign=i=>i<j ? -1 : i<positiveFrom ? 0 : 1;
    const cuts=[];
    if(k===1 && sign(0)!==sign(1)) cuts.push({row:wall,strict:true});
    if(z===2) cuts.push({row:scale(wall,-1n),strict:false});
    words.push({p,n,zero:z>0,lower:lower?[lower]:[],upper:upper?[upper]:[],cuts});
  }
  for(let j=0;j<=members.length;j++) {
    emit(j,0);
    if(j<members.length) emit(j,1);
  }
  if(k===1) emit(0,2);
  return words;
}

// The maximum of w*K on an interval with positive w uses its upper
// endpoint, and negative w uses its lower endpoint. Both are minima
// of available affine forms after multiplying by w. Only t=0 can
// contribute several choices to a given bound.
function sumBounds(indices,weights,words,side) {
  let sums=[[0n,0n,0n,1n]];
  for(let j=0;j<4;j++) {
    const weight=weights[j]*side;
    const parts=words[indices[j]][weight>0n ? "upper" : "lower"];
    if(!parts.length) return [];
    sums=sums.flatMap(sum=>parts.map(part=>norm([
      ...[0,1,2].map(i=>sum[i]*part[3]+part[i]*sum[3]*weight),sum[3]*part[3]
    ])));
  }
  return sums.map(sum=>sum.slice(0,3));
}

// All rays are nonnegative and represent points with x+y+z=1.
function clip(poly, row) {
  const values=poly.map(v => dot(v,row));
  if (values.every(v => v>=0n)) return poly;
  const out=[];
  for (let j=0;j<poly.length;j++) {
    const k=(j+1)%poly.length;
    if (values[j]>=0n) out.push(poly[j]);
    if (values[j]*values[k]<0n) {
      const a=values[j]>0n ? j : k;
      const b=values[j]>0n ? k : j;
      out.push(norm(poly[b].map((x,i) => values[a]*x-values[b]*poly[a][i])));
    }
  }
  return [...new Map(out.map(v => [v.join(),v])).values()];
}


const chartClosure=[[1n,0n,0n],[0n,1n,0n],[0n,0n,1n]];
for(const [k,group] of groups.entries()) {
  if(k===0) continue;
  for(let j=1;j<group.length;j++) {
    const row=difference(group[j-1].threshold,group[j].threshold);
    if(row.some(x=>x<0n)) throw Error("fixed pencil order");
    if(k===1&&j===1) {
      if(row.join()!==wall.join()) throw Error("wrong B=17t tie");
    } else if(!row[1]&&!row[2]) throw Error("unexpected equality");
  }
}
let states=[{a:endpointBits[24],b:0n,words:[],
             polygon:chartClosure,strict:[[0n,1n,0n],[0n,0n,1n]]}];
const stages=[];
for(let k=0;k<groups.length;k++) {
  const out=[];
  const stage={visits:0,direct:0,algebra:0,capacity:0,survivors:0,before:checks};
  const wordsForPencil=k?fixedPatterns(groups[k],k):variablePatterns(groups[k]);
  for(const state of states) for(const word of wordsForPencil) {
    stage.visits++;
    const a=state.a|word.p, b=state.b|word.n;
    if(count(a)>31 || count(b)>31) {stage.direct++;continue;}
    const words=[...state.words,word];
    let polygon=state.polygon;
    const strict=[...state.strict];
    function retain(row,isStrict) {
      polygon=clip(polygon,row);
      if(isStrict && polygon.every(v=>dot(v,row)===0n)) polygon=[];
      if(isStrict && polygon.some(v=>dot(v,row)===0n)) strict.push(row);
    }
    for(const {row,strict:isStrict} of word.cuts) retain(row,isStrict);
    for(const {indices,weights} of circuits[k]) {
      if(!polygon.length) break;
      const singleton=indices.every(i=>words[i].zero);
      for(const side of [1n,-1n]) {
        for(const row of sumBounds(indices,weights,words,side)) {
          if(!polygon.length) break;
          retain(row,!singleton);
        }
      }
    }
    if(!polygon.length || strict.some(row=>polygon.every(v=>dot(v,row)===0n))) {stage.algebra++;continue;}
    if(!can(a,5) || !can(b,5)) {stage.capacity++;continue;}
    out.push({a,b,words,polygon,strict:strict.filter(row=>polygon.some(v=>dot(v,row)===0n))});
  }
  stage.survivors=out.length;
  stage.checks=checks-stage.before;
  delete stage.before;
  stages.push(stage);
  states=out;
}
return {endpoints:P.length,germs:G.length,linearMasks:Q.length,variablePatterns:variablePatterns(groups[0]).length,checks,stages,
        final:states.map(x=>{
          const vertices=x.polygon.filter(v=>dot(v,wall)===0n);
          return {a:x.a.toString(16),b:x.b.toString(16),
            onWall:vertices.length>0 && x.strict.every(row=>vertices.some(v=>dot(v,row)>0n)),
            interior:x.polygon.some(v=>dot(v,wall)>0n)};
        })};
